### Архитектура: `SaveManager` (Autoload) + `Saveable` интерфейс

**Принцип:**  
1. **Глобальный менеджер** — один вызов `SaveManager.request_save()` из любого места.  
2. **Интерфейс `Saveable`** — каждый узел, который хочет сохраняться, реализует `_get_save_data()` / `_load_save_data(data)`.  
3. **Синхронный JSON** — для «в любой момент» (пауза, диалог, переход сцены) достаточно быстрого `FileAccess.store_string`.  
4. **Слот «Autosave» + ручные слоты** — перезаписываем `autosave.json` при каждом запросе, ручные — в `save_1.json`…`save_N.json`.

---

### 1. Autoload `SaveManager.gd`
```gdscript
# autoload/SaveManager.gd
extends Node
class_name SaveManager

signal save_completed(slot: String, success: bool)
signal load_completed(slot: String, success: bool)

@export var max_manual_slots: int = 3
@export var autosave_slot_name: String = "autosave"

# Внутренний кэш: { "node_path": { "prop": value } }
var _pending_data: Dictionary = {}

func _ready() -> void:
    # Автосохранение при выходе из игры / потере фокуса
    get_tree().notification_received.connect(_on_notification)

func _on_notification(what: int) -> void:
    if what in [MainLoop.NOTIFICATION_WM_QUIT_REQUEST, MainLoop.NOTIFICATION_WM_GO_BACK_REQUEST, MainLoop.NOTIFICATION_APPLICATION_FOCUS_OUT]:
        request_save(autosave_slot_name, silent:=true)

# === ПУБЛИЧНЫЙ API ===

# Вызывайте откуда угодно: SaveManager.request_save() или request_save("slot_1")
func request_save(slot: String = "", silent: bool = false) -> void:
    _pending_data.clear()
    _collect_save_data(get_tree().current_scene)

    var data = {
        "meta": {
            "timestamp": Time.get_unix_time_from_system(),
            "version": ProjectSettings.get_setting("application/config/version"),
            "scene": get_tree().current_scene.scene_file_path,
            "playtime": Time.get_ticks_msec() / 1000.0
        },
        "nodes": _pending_data
    }

    var path = _slot_to_path(slot if slot else autosave_slot_name)
    var success = _write_json(path, data)

    if not silent:
        save_completed.emit(slot if slot else autosave_slot_name, success)

func request_load(slot: String = "") -> bool:
    var path = _slot_to_path(slot if slot else autosave_slot_name)
    if not FileAccess.file_exists(path):
        return false

    var data = _read_json(path)
    if not data:
        return false

    # 1. Смена сцены, если нужно
    if data.meta.has("scene") and data.meta.scene != get_tree().current_scene.scene_file_path:
        var err = get_tree().change_scene_to_file(data.meta.scene)
        if err != OK:
            push_error("SaveManager: Failed to change scene to ", data.meta.scene)
            return false
        # Ждём готовности новой сцены
        await get_tree().process_frame

    # 2. Восстановление данных
    _apply_save_data(data.nodes)
    load_completed.emit(slot if slot else autosave_slot_name, true)
    return true

func get_save_info(slot: String) -> Dictionary:
    var path = _slot_to_path(slot)
    if not FileAccess.file_exists(path): return {}
    var data = _read_json(path)
    return data.meta if data else {}

func list_saves() -> Array[Dictionary]:
    var res = []
    for i in range(max_manual_slots + 1):
        var name = autosave_slot_name if i == 0 else "save_%d" % i
        var info = get_save_info(name)
        if not info.is_empty():
            info.slot = name
            res.append(info)
    return res

# === ВНУТРЕННЕЕ ===

func _collect_save_data(node: Node) -> void:
    if node.has_method("_get_save_data"):
        var data = node._get_save_data()
        if data:
            _pending_data[node.get_path()] = data
    for child in node.get_children():
        _collect_save_data(child)

func _apply_save_data(data: Dictionary) -> void:
    for node_path, node_data in data:
        var node = get_node_or_null(node_path)
        if node and node.has_method("_load_save_data"):
            node._load_save_data(node_data)
        else:
            push_warning("SaveManager: Node not found or not Saveable: ", node_path)

func _slot_to_path(slot: String) -> String:
    return "user://saves/%s.json" % slot

func _write_json(path: String, data: Dictionary) -> bool:
    var dir = "user://saves"
    if not DirAccess.dir_exists_absolute(dir):
        DirAccess.make_dir_recursive_absolute(dir)
    var f = FileAccess.open(path, FileAccess.WRITE)
    if f == null: return false
    f.store_string(JSON.stringify(data, "\t"))
    return true

func _read_json(path: String) -> Dictionary:
    var f = FileAccess.open(path, FileAccess.READ)
    if f == null: return {}
    var text = f.get_as_text()
    var result = JSON.parse_string(text)
    return result if typeof(result) == TYPE_DICTIONARY else {}
```

---

